"""Merge the readable Tahoma Latin slots into the Basit Arabic family."""
from pathlib import Path
import gen_font as g

ROOT = Path(__file__).resolve().parents[1]


def merge(target, latin, output):
    base = g.parse_glcd_header(target)
    overlay = g.parse_glcd_header(latin)
    if base.height != overlay.height or overlay.first != 0x20:
        raise SystemExit("font dimensions or first character do not match")
    original_digits = {code: base.get_glyph(code) for code in range(0x30, 0x3A)}
    for code in range(0x20, 0x80):
        # Western and Indic digits are generated by build_digit_fonts.py.
        # Never overwrite them with a generic Latin font.
        if 0x30 <= code <= 0x39:
            continue
        glyph = overlay.get_glyph(code)
        if glyph is not None:
            base.set_glyph_cols(code, glyph)
    assert all(base.get_glyph(code) == glyph
               for code, glyph in original_digits.items()), \
        "Latin overlay must not replace dedicated digit artwork"
    base.save_c(output, Path(output).stem)
    print(f"wrote {output}: Latin 0x20..0x7F from {latin}")


def main():
    merge(ROOT / "lib/DMDESP/fonts/BasitFont7.h",
          ROOT / "lib/DMDESP/fonts/Tahoma7.h",
          ROOT / "lib/DMDESP/fonts/BasitFont7.h")
    merge(ROOT / "lib/DMDESP/fonts/BasitFont16.h",
          ROOT / "lib/DMDESP/fonts/Tahoma16.h",
          ROOT / "lib/DMDESP/fonts/BasitFont16.h")
    merge(ROOT / "lib/DMDESP/fonts/BasitFont7Indic.h",
          ROOT / "lib/DMDESP/fonts/Tahoma7.h",
          ROOT / "lib/DMDESP/fonts/BasitFont7Indic.h")
    merge(ROOT / "lib/DMDESP/fonts/BasitFont16Indic.h",
          ROOT / "lib/DMDESP/fonts/Tahoma16.h",
          ROOT / "lib/DMDESP/fonts/BasitFont16Indic.h")


if __name__ == "__main__":
    main()
